import { useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { Segmented } from '@/components/ui/Segmented.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import {
  ASSISTANTS_PAGE_URL,
  CHATGPT_PLUGINS_URL,
  CLAUDE_DIRECTORY_URL,
  mcpAddress,
  type Assistant,
} from './connectAssistant.js';
import styles from './ConnectAssistantSheet.module.css';

const STEPS: Record<Assistant, readonly MessageKey[]> = {
  chatgpt: [
    'connectHelp.chatgptStep1',
    'connectHelp.chatgptStep2',
    'connectHelp.chatgptStep3',
    'connectHelp.chatgptStep4',
  ],
  claude: ['connectHelp.claudeStep1', 'connectHelp.claudeStep2', 'connectHelp.claudeStep3'],
  claudeCode: ['connectHelp.claudeCodeStep1', 'connectHelp.claudeCodeStep2'],
};

/**
 * How to connect ChatGPT, Claude or Claude Code to Lexpad. The connection
 * itself is made in the assistant and approved on the consent screen
 * (`features/connect`); this sheet only tells somebody where to click and
 * hands them the address. Nothing here talks to the server.
 */
export function ConnectAssistantSheet({
  say,
  onClose,
  initial = 'chatgpt',
}: {
  say: (message: string, isError?: boolean) => void;
  onClose: () => void;
  /** The tab it opens on: Lexpad everywhere opens the row that was tapped. */
  initial?: Assistant;
}): React.JSX.Element {
  const [assistant, setAssistant] = useState<Assistant>(initial);
  const address = mcpAddress();
  const command = `claude mcp add --transport http lexpad ${address}`;

  const copy = (value: string): void => {
    platform.share
      .text(value)
      .then(() => {
        say(t('connectHelp.copied'));
      })
      .catch(() => {
        say(t('error.generic'), true);
      });
  };

  const openUrl = assistant === 'chatgpt' ? CHATGPT_PLUGINS_URL : CLAUDE_DIRECTORY_URL;

  return (
    <Sheet title={t('connectHelp.title')} onClose={onClose}>
      <div className={styles.body}>
        <p className={styles.lead}>{t('connectHelp.lead')}</p>
        <Segmented
          label={t('connectHelp.choose')}
          block
          value={assistant}
          options={[
            { value: 'chatgpt', label: t('connectHelp.chatgpt') },
            { value: 'claude', label: t('connectHelp.claude') },
            { value: 'claudeCode', label: t('connectHelp.claudeCode') },
          ]}
          onChange={setAssistant}
        />

        {/* Claude lists Lexpad in its directory, so there is no address to copy. */}
        {assistant === 'claudeCode' && (
          <CodeBox label={t('connectHelp.commandLabel')} value={command} onCopy={copy} />
        )}
        {assistant === 'chatgpt' && (
          <CodeBox label={t('connectHelp.addressLabel')} value={address} onCopy={copy} />
        )}

        <ol className={styles.steps}>
          {STEPS[assistant].map((key) => (
            <li key={key}>{t(key)}</li>
          ))}
        </ol>

        {assistant !== 'claudeCode' && (
          <>
            <a className={styles.open} href={openUrl} target="_blank" rel="noopener noreferrer">
              {assistant === 'chatgpt' ? t('connectHelp.openChatgpt') : t('connectHelp.openClaude')}
            </a>
            <p className={styles.note}>{t('connectHelp.phoneNote')}</p>
          </>
        )}

        <a className={styles.more} href={ASSISTANTS_PAGE_URL} target="_blank" rel="noopener noreferrer">
          {t('connectHelp.more')}
        </a>
      </div>
    </Sheet>
  );
}

function CodeBox({
  label,
  value,
  onCopy,
}: {
  label: string;
  value: string;
  onCopy: (value: string) => void;
}): React.JSX.Element {
  return (
    <div className={styles.codeBox}>
      <code className={styles.code} dir="ltr" aria-label={label}>
        {value}
      </code>
      <button
        type="button"
        className={styles.copy}
        aria-label={t('connectHelp.copyLabel', { what: label })}
        onClick={() => {
          onCopy(value);
        }}
      >
        <Icon name="copy" size={16} weight={2} />
        {t('connectHelp.copy')}
      </button>
    </div>
  );
}
