/**
 * The six things worth doing once, and how the app knows they happened.
 *
 * Every step is *derived* rather than recorded: a word exists, a card has an
 * AI source, a day has reviews, a reminder has a time. Nothing here writes a
 * "you did it" flag, which means the list cannot drift from the truth, needs
 * no new sync surface, and is already correct on a device that has only just
 * pulled somebody's notebook down.
 *
 * The extension is the exception and cannot be derived locally: the
 * extension marks the words it adds as `manual` or `ai`, the same as
 * anything typed by hand, so a word gives it away not at all. What it does
 * leave behind is a session on the account, which is a network read. That
 * one milestone is remembered once seen, because it is a thing that
 * happened rather than a state that can come and go.
 */
import { db, getMeta, setMeta, type LexpadDb } from '@/db/schema.js';
import { loadHistory, loadSettings } from '@/db/repo.js';
import { localTimeZone } from '@/lib/format.js';

/** The steps, in the order they are worth doing. */
export const STEP_IDS = ['word', 'ai', 'practise', 'extension', 'assistant', 'reminder'] as const;

export type StepId = (typeof STEP_IDS)[number];

export interface Progress {
  done: readonly StepId[];
  /** How many are done, and how many there are. */
  count: number;
  total: number;
  complete: boolean;
}

/** How far back to look for a practice session. A habit, not a fortnight. */
const HISTORY_DAYS = 400;

/**
 * Works out which steps are done from what is already stored.
 *
 * The extension is read from its own remembered flag rather than from the
 * network, so this stays a local query and Today keeps rendering from
 * IndexedDB on the first frame.
 */
export async function progress(database: LexpadDb = db): Promise<Progress> {
  const [words, settings, history, extension] = await Promise.all([
    database.words.toArray(),
    loadSettings(database),
    loadHistory(HISTORY_DAYS, localTimeZone(), new Date(), database),
    getMeta('extensionSeen', database),
  ]);

  const done: StepId[] = [];
  if (words.length > 0) done.push('word');
  if (words.some((word) => word.source === 'ai')) done.push('ai');
  if (history.some((day) => day.reviewed > 0)) done.push('practise');
  if (extension) done.push('extension');
  // A word an assistant saved carries its own source, so this one is derived too.
  if (words.some((word) => word.source === 'assistant')) done.push('assistant');
  if ((settings?.reminderTime ?? '') !== '') done.push('reminder');

  return { done, count: done.length, total: STEP_IDS.length, complete: done.length === STEP_IDS.length };
}

/** Remembers that the extension has been connected at least once. */
export async function noteExtension(seen: boolean, database: LexpadDb = db): Promise<void> {
  if (!seen) return;
  await setMeta('extensionSeen', true, database);
}

/**
 * Settles, once, whether this account is offered the list.
 *
 * An account that already has words and has practised is not new, whatever
 * else is unticked, and telling somebody who has used the app for a month to
 * "add your first word" would be the app failing to notice them. A device
 * that has just pulled an existing notebook down looks the same, which is
 * right: that person is not new either.
 *
 * This writes, so it must never be called from inside a live query — the
 * write would retrigger the very query that made it. Callers run it once
 * from an effect and read the answer back through `getMeta`.
 */
export async function decideOnce(database: LexpadDb = db): Promise<void> {
  if ((await getMeta('getStarted', database)) !== null) return;
  const here = await progress(database);
  const established = here.done.includes('word') && here.done.includes('practise');
  await setMeta('getStarted', { offered: !established, celebrated: established }, database);
}

/**
 * Whether the finish has been celebrated yet, and marking it done so it
 * happens once rather than on every visit to Today.
 */
export async function celebrated(database: LexpadDb = db): Promise<boolean> {
  return (await getMeta('getStarted', database))?.celebrated ?? false;
}

export async function noteCelebrated(database: LexpadDb = db): Promise<void> {
  const decided = await getMeta('getStarted', database);
  await setMeta('getStarted', { offered: decided?.offered ?? true, celebrated: true }, database);
}
