/**
 * Where each surface is installed from. These are the stores' and the
 * site's public addresses, not settings: nothing on the server knows them,
 * the app has to name them to send anybody there, and they move only if a
 * store listing or the site does. Each carries `ref`, so a visit from the
 * app can be told apart from any other on the site's own page counts.
 *
 * Whether a surface may be offered at all is not decided here: that is the
 * server's `release` for it (the cross_promotion flag), so the Android link
 * appears the day an operator marks the app live, without a release of this
 * one.
 */

import type { MessageKey } from '@/i18n/index.js';

/** The browser extension's listings: the public pages, no locale, no account parameters. */
export const EXTENSION_STORES = {
  chrome: 'https://chromewebstore.google.com/detail/cmadljhpbngcceagpjfladgjjjnegikk',
  // Microsoft Edge Add-ons, live since 2026-10-12.
  edge: 'https://microsoftedge.microsoft.com/addons/detail/lexpad/ljffeocghlpgngjjnlpadioajopgpdhb',
  firefox: 'https://addons.mozilla.org/firefox/addon/lexpad/',
} as const;

/** The button that opens each store's listing, in this browser's words. */
export const STORE_LABEL = {
  chrome: 'everywhere.addChrome',
  edge: 'everywhere.addEdge',
  firefox: 'everywhere.addFirefox',
} as const satisfies Record<keyof typeof EXTENSION_STORES, MessageKey>;

/** The site's page about the extension, which links every store: what a phone sends to a computer. */
export const EXTENSION_PAGE_URL = 'https://lexpad.app/features/extension';

/** The desktop app's page and downloads (macOS and Windows), on the site. */
export const DESKTOP_PAGE_URL = 'https://lexpad.app/features/desktop';

/** The Android app on Google Play (package app.lexpad.android; production since 2026-10-17). */
export const PLAY_URL = 'https://play.google.com/store/apps/details?id=app.lexpad.android';

/**
 * The iPhone and iPad app on the App Store: Apple's id for the app record
 * (`appAppleId` in ios/scripts/asc-products.json, bundle app.lexpad.ios).
 * The page exists only once Apple releases the app, which is why nothing
 * links here until the server marks `ios` live.
 */
export const APP_STORE_URL = 'https://apps.apple.com/app/id6822224295';

/**
 * The Mac app's download page, at the box that starts the download (the
 * site's rule: a Download button goes to `<page>#start`, never to the file).
 * Signed and notarized by Apple since 0.3.7.
 */
export const MAC_DOWNLOAD_URL = 'https://lexpad.app/download/mac#start';

/** The Windows app in the Microsoft Store, written once in `lib/externalLinks.ts`. */
export { MICROSOFT_STORE_URL } from '@/lib/externalLinks.js';

/** Adds the place in the app a link was opened from, for the site's and stores' own counts. */
export function withRef(url: string, ref: string): string {
  const parsed = new URL(url);
  parsed.searchParams.set('ref', ref);
  return parsed.href;
}

/** The study's names for the cards (N1–N8), carried as `ref` on every link a card opens. */
export const NUDGE_REF = {
  extension: 'N1',
  desktop_safari: 'N2',
  desktop_power: 'N3',
  on_your_computer: 'N4',
  on_your_phone: 'N5',
  android_browser: 'N6',
  connector: 'N7',
  kindle: 'N8',
} as const;
