import { platform } from '@/lib/platform/index.js';

export type Assistant = 'chatgpt' | 'claude' | 'claudeCode';

/*
 * Where each assistant connects Lexpad (ChatGPT's plugin settings, Lexpad's
 * page in Claude's connector directory), and the public page
 * about assistants. These are other services' addresses (and the landing
 * site's), not Lexpad data: nothing on the server knows them, so they are
 * named here once.
 */
export const CHATGPT_PLUGINS_URL = 'https://chatgpt.com/plugins';
export const CLAUDE_DIRECTORY_URL = 'https://claude.ai/directory/lexpad';
export const ASSISTANTS_PAGE_URL = 'https://lexpad.app/features/assistants';

/**
 * The MCP endpoint lives on the API host, so the address is read from the
 * API address this build was given rather than written down.
 */
export function mcpAddress(): string {
  return new URL('/mcp', platform.env.apiUrl || window.location.origin).href;
}
