import { useEffect, useRef, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { serverNow } from '@/lib/serverClock.js';
import { subscribe } from '@/lib/ticker.js';
import { OfferCountdown } from './OfferCountdown.js';
import { closingWords } from './night.js';
import { OFFER_LAST_HOURS, type Offer } from './offer.js';

const HOUR = 3_600_000;

/**
 * The closing line of a night card (uiux spec 2026-10-24 §3): the real end
 * always, "Until Wed, Dec 2, 11:59 PM your time", and in the last day "Ends
 * today at 11:59 PM, your time" in minute steps. On a surface the learner
 * opened (the Plan head, the trial-end screen) the last day is the live
 * countdown instead, in its one-line night tone, within the campaign's own
 * live-seconds window. The end is always the offer's latest `closesAt`
 * (F5): an outage extension replaces it on the next plan read. When the
 * end passes on screen, `onEnded` asks for the plan again, once.
 */
export function NightClosing({
  offer,
  opened = false,
  className,
  onEnded,
}: {
  offer: Offer;
  opened?: boolean;
  className?: string | undefined;
  onEnded?: (() => void) | undefined;
}): React.JSX.Element | null {
  const [now, setNow] = useState(() => serverNow());
  useEffect(() => subscribe('minute', setNow), []);
  const end = Date.parse(offer.closesAt);
  const over = !Number.isNaN(end) && now >= end;
  const told = useRef(false);
  useEffect(() => {
    if (!over || told.current) return;
    told.current = true;
    onEnded?.();
  }, [over, onEnded]);
  useEffect(() => {
    // The minute ticker may land a little after the end; the end itself is not missed.
    if (Number.isNaN(end) || end <= serverNow()) return;
    const timer = window.setTimeout(
      () => {
        setNow(serverNow());
      },
      Math.min(end - serverNow() + 50, 2 ** 31 - 1),
    );
    return () => {
      window.clearTimeout(timer);
    };
  }, [end]);
  const look = offer.creative?.look;
  if (opened && !Number.isNaN(end) && end - now <= OFFER_LAST_HOURS * HOUR && end > now) {
    return (
      <OfferCountdown
        closesAt={offer.closesAt}
        surface="opened"
        tone="night"
        liveSecondsFromHours={look?.liveSecondsFromHours ?? OFFER_LAST_HOURS}
        style={look?.countdownStyle ?? 'auto'}
      />
    );
  }
  const words = closingWords(offer.closesAt, new Date(now));
  if (words === undefined) return null;
  return (
    <p className={className}>
      <Icon name="clock" size={15} weight={2} />
      {words}
    </p>
  );
}
