/**
 * "What Pro did for you" as rows (uiux offers spec C6): one row per count
 * above zero, in a fixed order, each with its practice tint. Nothing is
 * estimated; a zero is left out.
 */
import type { ApiTrialFacts } from '@/api/types.js';
import type { IconName } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';

type ReceiptLabel = 'receipt.lex' | 'receipt.texts' | 'receipt.cards' | 'receipt.notebooks';

const ROWS: { key: keyof ApiTrialFacts; label: ReceiptLabel; icon: IconName; tint: 'a' | 'g' | 'i' | 't' }[] =
  [
    { key: 'lexQuestions', label: 'receipt.lex', icon: 'sparkles', tint: 'a' },
    { key: 'textsSearched', label: 'receipt.texts', icon: 'search', tint: 'g' },
    { key: 'aiCards', label: 'receipt.cards', icon: 'cards', tint: 'i' },
    { key: 'extraNotebooks', label: 'receipt.notebooks', icon: 'notebook', tint: 't' },
  ];

/** Keys for the loading rows, so the box keeps a height while the counts come. */
export const RECEIPT_PLACEHOLDERS = ['one', 'two'] as const;

export interface ReceiptRow {
  label: string;
  icon: IconName;
  tint: 'a' | 'g' | 'i' | 't';
  count: number;
}

export function receiptRows(facts: ApiTrialFacts | null): ReceiptRow[] {
  if (facts === null) return [];
  return ROWS.flatMap((row) => {
    const value = facts[row.key];
    const count = typeof value === 'number' && Number.isFinite(value) && value > 0 ? Math.floor(value) : 0;
    return count > 0 ? [{ label: t(row.label), icon: row.icon, tint: row.tint, count }] : [];
  });
}

/** The trial's length in days, from the facts' own window, or undefined. */
export function trialLengthDays(facts: ApiTrialFacts | null): number | undefined {
  if (facts === null) return undefined;
  const start = Date.parse(facts.startedAt);
  const end = Date.parse(facts.endsAt);
  if (Number.isNaN(start) || Number.isNaN(end) || end <= start) return undefined;
  return Math.round((end - start) / 86_400_000);
}
