/**
 * Celebrations as a screen uses them: the switch and this device's state,
 * read live, with the baseline settled the first time a screen that
 * celebrates opens (never inside the live query: the write would retrigger
 * the query that made it). The baseline's code is loaded only then.
 */
import { useEffect } from 'react';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { CELEBRATE_OFF, loadCelebrate, type CelebrateView } from './view.js';

export function useCelebrate(): CelebrateView & { ready: boolean } {
  // An async arrow: Dexie follows the reads past the first await only inside an async querier.
  const read = useLiveQuery<CelebrateView | null>(async () => loadCelebrate(), null, []);
  const view = read ?? CELEBRATE_OFF;
  useEffect(() => {
    if (view.on && view.state === null && view.synced) {
      void import('./state.js').then((state) => state.settleCelebrate()).catch(() => undefined);
    }
  }, [view.on, view.state, view.synced]);
  return { ...view, ready: read !== null };
}
